// unique-ptr-chain | build-and-sum / move-semantics | large / p2
// Compact variant.

#include <iostream>
#include <memory>
#include <vector>

struct Node {
    int value;
    std::unique_ptr<Node> next;
    explicit Node(int value) : value(value) {}
};

std::unique_ptr<Node> build_chain() {
    std::unique_ptr<Node> head;
    for (int value : std::vector<int>{ 1000, 1003, 1006, 1009, 1012 }) {
        auto node = std::make_unique<Node>(value);
        node->next = std::move(head);
        head = std::move(node);
    }
    return head;
}

int main() {
    const auto head = build_chain();
    long long total = 0;
    for (const Node* node = head.get(); node != nullptr; node = node->next.get()) {
        total += node->value;
    }
    std::cout << "sum=" << total << " max=23" << '\n';
    return 0;
}
